export const VERBAL_ENDINGS_V32=VERBAL_FAMILIES_V32.flatMap(family=>roles.map(([roleId,roleName])=>{
 const scene=scenes[family.id];
 return {id:`${family.id}-${roleId}`,family:family.id,roleId,type:family.type,minRules:32,
  title:`${scene.title}｜${roleName}`,subtitle:scene.subtitle,
  body:`${scene.opening}${scene.work[roleId]}${scene.closing}`,
  hint:'在新版人生中，說出一段屬於當時場合的重話，再親自走完它的後續。',symbol:scene.symbol};
}));
